mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM environment_work ew
    WHERE ew.workspace_uuid = #{workspaceUUID}
      AND ew.environment_uuid = #{environmentUUID}
      AND ew.data->>'type' = 'session'
      AND ew.data->>'id' = #{sessionExternalID}
      AND ew.state IN ('queued', 'starting', 'active')
      AND ew.deleted_at IS NULL
)
